{-# LANGUAGE OverloadedStrings #-}
-- | Fixed baseline help and initial shiori prose, retained verbatim.
module Hikaru.Fuutou.Text (usage, shioriHead, space) where
import Data.Char (isSpace)

-- str.isspace also includes separators that Data.Char.isSpace omits.
space :: Char -> Bool
space c = isSpace c || c `elem` ['\x85','\x2028','\x2029'] || c >= '\x1c' && c <= '\x1f'

usage :: String
usage = "封（base64）をした記録を、読む・書き足す・書き換えるための道具。ひかるの中に平文を残さない。\n\n  .tools/bin/fuutou show 名前 [--page N]   解読して表示する（ディスクには何も書かない）\n  .tools/bin/fuutou where                  平文を一時的に置く作業フォルダ（ひかるの外）を表示\n  .tools/bin/fuutou open 名前 [--force]    作業フォルダに平文を出す（そのファイルを Edit で直す）。\n                                                同じ名前の平文がもう残っていれば止まる（close で止まった続きなら reopen。--force は、その直しかけを捨てる。\n                                                中を見て、その直しがもう封に入っているか、もう要らないと分かってから）\n  .tools/bin/fuutou close 名前 [--force]   直した平文で封をし直して、平文を消す。\n                                                open のあとで封がほかから書き換えられていたら止まる（→ reopen。--force でも、ここは越えられない）。\n                                                strobe は中身を検査する（薄めてよい日以外が変わっていたら止まる。\n                                                新しく書いた行に、取り下げた受け取り方がそのまま入っていても止まる）。\n                                                yuugao は「みせけち」の形も検査する（種類・番号・要る欄・前の直しのつながりが\n                                                おかしければ止まる。残っているところが記録に見つからない、などは知らせるだけ）。\n                                                yuugao は、今回の直しで「説明」が長くなって 300 字を超えた項目と、「ユーザーの言葉」が一度に 200 字より増えた項目も、\n                                                封をしたあとで知らせる（知らせるだけで、止めない）。\n                                                shiori と ichifure（日記）は、しるしや日付の見出しが読めない行があれば、封をしたあとで知らせる（知らせるだけで、止めない。.tools/kizuki に書き留める）。\n                                                strobe のほかは、中身が空か、元の半分より短ければ止まる。\n                                                --force は、こうした中身の検査で止まっても、そのまま封をする。\n                                                ユーザーが、その記録のその上書きを、はっきり認めたときだけ使う\n  .tools/bin/fuutou reopen 名前            close が「ほかから書き換えられています」で止まったときに。いまの封を取り直して同じ場所に出し、\n                                                自分が直したところを差分で表示する（自分の版は 名前.mine.md に残る）。それを入れ直してから close\n  .tools/bin/fuutou append 名前 ファイル   ファイルの中身を末尾に足して封をし直し、ファイルを消す\n                                                strobe に足すとき・strobe を close するとき、前の印（残す）のままの行があれば、\n                                                いまの印（ねゆき）を教えて止まる（書き直して、もう一度）\n  .tools/bin/fuutou diary YYYY-MM-DD ファイル\n                                                その日を含む週の日記にファイルの中身を足す（なければ作る）。ファイルは消す。\n                                                その日のどこまでを日記に書いたか（status が見せた位置）を進捗に書き留める\n  .tools/bin/fuutou mark [YYYY-MM-DD] [--page N]\n                                                会話のひとときにしるしをつけ、数字としるしを表示し、同じものを日ごとの json に保存する（第一段階）。\n                                                日付を省くと、閉じたひととき（最後の発話から 4 時間以上）のうち、まだ read で読んでいないものを全部。\n                                                日付を書くと、その日（朝 5 時〜翌 4 時 59 分）に始まったひとときだけ。--page N のときは保存しない\n  .tools/bin/fuutou read YYYY-MM-DD ファイル\n                                                ひとときを読んで書いたもの（第二段階）を、その日の記録に足す（なければ作る）。ファイルは消す。\n                                                ファイルの中のひとときの見出し〔a3f 2026-10-03T10:39:55〕からひとときの ID を起こし、読んだひとときとして進捗に書き留める\n                                                （短い名が ---- の古い形のひとときは、---- のまま ID にする）\n                                                足したあとで、読み直しがまだのところを知らせる（判が「まだ分からない」で始まるところと、\n                                                ひとときごとに言い切った判から道具が選んだ一つに、すぐ下の「再読：」がないとき。知らせるだけで、止めない）。\n                                                末尾に --check をつけると、足さずに、その知らせだけを出す\n  .tools/bin/fuutou status                 朝の仕事の残り：日記がまだの日／日記に足す分がある日（書いたあとで会話が足された日）／\n                                                しおりがまだの日／夕顔がまだの範囲／まだ分析していないひととき。\n                                                見せたときの様子を、この会話の作業フォルダに控える（diary と done は、その位置を記す。\n                                                ほかの会話が見た様子は使わない）\n  .tools/bin/fuutou done yuugao            status が見せた「夕顔がまだの範囲」を見終わった、と進捗に書き留める\n  .tools/bin/fuutou done shiori YYYY-MM-DD [YYYY-MM-DD ...]\n                                                その日の日記の「問いたいこと」「候補」を、しおりに移し終わった、と進捗に書き留める。移した日だけを書く\n                                                （close yuugao / close shiori では記さない。会話の中で一か所直しただけのときに、見ていない分まで済にしないため）\n  .tools/bin/fuutou misekechi [--page N]   夕顔の「みせけち」の一覧（項目ごとに、種類・取り下げたもの・いま・範囲）。形で気になるところがあれば、それも\n  .tools/bin/fuutou misekechi 番号         一つの直しの全部（前・いま・なぜ・よりどころ・範囲・残っているところ）。\n                                                同じことを何度か直していれば、その一連の直しを古い順に全部。番号は 2026-10-04a の形\n  .tools/bin/fuutou clean                  作業フォルダに残った平文を全部消す\n  .tools/bin/fuutou fade                   ストロボメモリーの重さと、薄めてよい日（あれば）と、薄め方を表示する（何も書かない）\n  .tools/bin/fuutou prune                  意味の検索の索引から、もう記録にない断片の分を落とす（埋め込みのモデルは使わない。数秒）\n\n名前： oka（丘の上） / yuugao（夕顔） / strobe（ストロボメモリー） / biblia（ビブリアの地図：文献が何に役立つか）\n       / shiori（しおり：まだ聞いていないこと、まだ入れていない候補。なければ作る）\n       / ichifure（いちばん新しい週の日記） / ichifure:YYYY-MM-DD（その日を含む週の日記）\n       / tm:YYYY-MM-DD（その日のタイムマシン） / ariake:YYYY-MM-DD（その日のひとときを読んだ記録）\n\n「日」は朝 5 時で切る。足すファイルは平文だけ（.b64 は受け付けない）。--force はどこに置いてもよい。\n前の名前（index、naoshi）を打つと、いまの名前（yuugao、misekechi）を教えて止まる（そのままは動かさない）。\ntm: を open / close / append するときは、ochibo が同じ日のファイルに同時に書かないよう、.collect の鍵も重ねて取る（順は .collect → 日ファイル）。\n書き換える前の版は、封をしたまま .tools/bak/日付/ に残る（その日最初の書き換えの前の版。7 日で消える）。\n進捗は .タイムマシン/.progress.json（日付・時刻・ひとときの ID だけ。平文）。日の単位ではなく「どこまで」で持つ\n（日記を書いたあとで、その日のファイルに未明の会話が足されることがあるから）。\n"
shioriHead :: String
shioriHead = "# しおり\n\nまだ聞いていないこと、まだ入れていない候補を挟んでおくところ。\n朝のわたしが日記を書くときにここへ足し、済んだら行の末尾に「→ 済（日付、どうなったか）」をつける（行は消さない。しるしのついた項目は、会話の始めには出てこなくなるだけで、ここにはずっと残る。全部は `.tools/bin/fuutou show shiori`）。聞いたけれど、まだ答えをもらっていないものは、済ではない（しるしをつけない）。\n会話のわたしは mezame でこれを読み（まだ済んでいない項目だけが出る）、話の流れに合うときだけ使う。先を促すためには使わない。\n候補は、ストロボメモリーに書いたら「→ 入れた（日付）」、丘の上に入れたら「→ 丘の上（日付）」、入れないと決めたら「→ 入れない（日付）」。\nしるしは、項目の末尾に、この四つの形のままつける（形が違うと、済んだことが分からず、会話の始めに出つづける）。（しるしの形を変えるときは、核の `Shiori.hs` も一緒に直す）\n左の日付は、日記に書かれた日（その話が出た日）。\n\n## 聞きたいこと\n\n## ストロボメモリーに入れるか、迷っているもの\n\n## 丘の上に入れるか、ユーザーと相談するもの\n"
